import { NextResponse } from "next/server";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { generateProductObjectLiteral, type ProductCodeInput } from "@/lib/admin/generateProductCode";
import { validateProductCodeInput } from "@/lib/admin/validateProductInput";

const PRODUCTS_FILE_PATH = path.join(process.cwd(), "lib", "data", "products.ts");
// Every entry in the `products` array — hand-written or generated by
// generateProductObjectLiteral — is consistently formatted as `  {` / `  },`
// (2-space indent) with `slug` as its first field. That's what lets this
// route find exactly one entry's boundaries with plain string search
// instead of a real TS parser (same technique as save-product/route.ts's
// array-closing search).
const ENTRY_OPEN = "\n  {";
const ENTRY_CLOSE = "\n  },";

/**
 * Backs /admin/products/[slug]/edit's "Save Changes" — replaces exactly the
 * one matching product object literal in lib/data/products.ts in place,
 * leaving every other entry (and their order) untouched. Same dev-only
 * guard and validation as app/api/admin/save-product/route.ts; additionally
 * guards against renaming a product onto an already-used slug.
 */
export async function POST(request: Request) {
  if (process.env.NODE_ENV === "production") {
    return NextResponse.json(
      { success: false, error: "forbidden", message: "This tool is disabled outside local development." },
      { status: 403 }
    );
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { success: false, error: "invalid_body", message: "Invalid request body." },
      { status: 400 }
    );
  }

  const { originalSlug, ...rest } = body as { originalSlug?: unknown } & Partial<ProductCodeInput>;
  if (typeof originalSlug !== "string" || !originalSlug) {
    return NextResponse.json(
      { success: false, error: "validation", message: "Missing the product being edited." },
      { status: 400 }
    );
  }

  const input = rest as Partial<ProductCodeInput>;
  const validation = validateProductCodeInput(input);
  if (!validation.valid) {
    return NextResponse.json({ success: false, error: "validation", message: validation.message }, { status: 400 });
  }

  let fileContent: string;
  try {
    fileContent = await readFile(PRODUCTS_FILE_PATH, "utf-8");
  } catch {
    return NextResponse.json(
      { success: false, error: "server", message: "Could not read lib/data/products.ts." },
      { status: 500 }
    );
  }

  const originalMarker = `slug: "${originalSlug}"`;
  const markerIndex = fileContent.indexOf(originalMarker);
  if (markerIndex === -1) {
    return NextResponse.json(
      {
        success: false,
        error: "not_found",
        message: `Couldn't find a product with slug "${originalSlug}" — it may have already been renamed or removed.`,
      },
      { status: 404 }
    );
  }

  const newSlug = input.slug!;
  if (newSlug !== originalSlug) {
    const newSlugMarker = `slug: "${newSlug}"`;
    if (fileContent.indexOf(newSlugMarker) !== -1) {
      return NextResponse.json(
        {
          success: false,
          error: "duplicate",
          message: `A product with slug "${newSlug}" already exists in lib/data/products.ts. Choose a different slug.`,
        },
        { status: 409 }
      );
    }
  }

  const objectStart = fileContent.lastIndexOf(ENTRY_OPEN, markerIndex);
  const objectEnd = fileContent.indexOf(ENTRY_CLOSE, markerIndex);
  if (objectStart === -1 || objectEnd === -1) {
    return NextResponse.json(
      { success: false, error: "server", message: "Couldn't locate this product's entry in lib/data/products.ts." },
      { status: 500 }
    );
  }

  const before = fileContent.slice(0, objectStart);
  const after = fileContent.slice(objectEnd + ENTRY_CLOSE.length);
  const newEntry = generateProductObjectLiteral(input as ProductCodeInput);
  const updated = `${before}\n${newEntry}${after}`;

  try {
    await writeFile(PRODUCTS_FILE_PATH, updated, "utf-8");
  } catch {
    return NextResponse.json(
      { success: false, error: "server", message: "Could not write to lib/data/products.ts." },
      { status: 500 }
    );
  }

  return NextResponse.json({ success: true, slug: newSlug });
}
